import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';
import { CommonQuestionViewModel, ICommonQuestionViewModel } from '../../../../../data/model/site/SliderModel';

@Component({
  selector: 'app-common-questions',
  templateUrl: './common-questions.component.html',
  styleUrls: ['./common-questions.component.scss']
})
export class CommonQuestionsComponent implements OnInit {

  addForm: FormGroup;
  updateForm: FormGroup;
  segmentSelected = 'Add';
  selectedIndex = -1;
  list: ICommonQuestionViewModel[] = [];

  constructor(
    private siteService: SliderService,
    private fb: FormBuilder,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController,
    private router: Router) { }

  ionViewWillEnter() {

    this.getData();
  }

  ngOnInit(): void {

    this.addForm = this.fb.group({
      title: ['', [Validators.required, Validators.minLength(1)]],
      description: ['', [Validators.required, Validators.minLength(1)]],
      link: [''],
      isActive: [false],
      isImportant: [false]
    });

    this.updateForm = this.fb.group({
      id: ['', [Validators.required, Validators.min(1)]],
      title: ['', [Validators.required, Validators.minLength(1)]],
      description: ['', [Validators.required, Validators.minLength(1)]],
      link: [''],
      isActive: [false],
      isImportant: [false]
    });
  }

  getData() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetAllCommonQuestions().subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {

          this.list = res.data;
        } else {
          SharedIonic.toast(this.toastController, 'موردی یافت نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onSelect(index: number | string): void {

    this.selectedIndex = +index;

    this.updateForm.setValue({
      id: this.list[+index].id,
      title: this.list[+index].title,
      description: this.list[+index].description,
      link: this.list[+index].link,
      isActive: this.list[+index].isActive,
      isImportant: this.list[+index].isImportant
    });
  }

  async presentAlertConfirm(index) {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن به حذف هستید؟!؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'حذف',
          handler: () => {
            this.onDelete(index);
          }
        }
      ]
    });

    await alert.present();
  }

  onDelete(index: number | string): void {

    this.selectedIndex = +index;

    SharedIonic.loading(this.loadingController);

    this.siteService.RemoveCommonQuestion(this.list[this.selectedIndex].id).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (GResponse.SuccessStatus === res.status) {
          this.updateForm.setValue({
            id: '',
            title: '',
            description: '',
            link: '',
            isActive: false,
            isImportant: false
          });
          this.getData();
          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.unSuccessToast(this.toastController);
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.unSuccessToast(this.toastController);
      }
    );
  }

  onUpdate() {

    if (this.updateForm.valid || this.selectedIndex != 0) {

      SharedIonic.loading(this.loadingController);

      this.siteService.AddOrUpdateCommonQuestion(
        new CommonQuestionViewModel(
          this.updateForm.value.id,
          this.updateForm.value.title,
          this.updateForm.value.description,
          this.updateForm.value.link,
          this.updateForm.value.isActive,
          this.updateForm.value.isImportant
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.updateForm.setValue({
              id: '',
              title: '',
              description: '',
              link: '',
              isActive: false,
              isImportant: false
            });
            this.getData();
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

  onAdd() {

    if (this.addForm.valid) {

      SharedIonic.loading(this.loadingController);

      this.siteService.AddOrUpdateCommonQuestion(
        new CommonQuestionViewModel(
          0,
          this.addForm.value.title,
          this.addForm.value.description,
          this.addForm.value.link,
          this.addForm.value.isActive,
          this.addForm.value.isImportant
        )
      ).subscribe(
        res => {
          SharedIonic.dismissLoading(this.loadingController);
          if (GResponse.SuccessStatus === res.status) {
            this.addForm.setValue({
              title: '',
              description: '',
              link: '',
              isActive: false,
              isImportant: false
            });
            this.getData();
            SharedIonic.successToast(this.toastController);
          } else {
            SharedIonic.unSuccessToast(this.toastController);
          }
        },
        err => {
          SharedIonic.dismissLoading(this.loadingController);
          SharedIonic.unSuccessToast(this.toastController);
        }
      );
    }
  }

}
